// 教学内容独立于交互与3DScenario，可直接扩充每层的Protocol和知识点。
const protocol = (name, title, brief, topics, meta = '', source = '') => ({name,title,brief,topics,meta,source});
const topic = (title, text) => ({title,text});
export const PROTOCOLS = {
  http: protocol('HTTP','Rules for web pages and APIs','Clients send requests and servers return responses. HTTP defines semantics, methods, status codes and message formats.',[
    topic('Requests and responses','A request contains a method, target resource and headers, with an optional body. A response contains a status code, headers and an optional body. GET usually reads resources; POST usually submits data.'),
    topic('Status codes','2xx means success, 3xx redirection, 4xx a client-side request problem, and 5xx a server-side problem. 404 means the resource was not found; 500 means an internal server error.'),
    topic('Versions and transport','HTTP/1.1 and HTTP/2 commonly use TCP. HTTP/3 uses QUIC, usually over UDP. HTTPS protects HTTP with mechanisms such as TLS; TCP itself does not supply encryption.'),
    topic('Statelessness and sign-in','HTTP semantics do not require servers to remember earlier requests. Applications can manage sign-in with cookies and session identifiers. One login session can span several TCP connections.')
  ],'80 / 443','https://www.rfc-editor.org/rfc/rfc9110.html'),
  dns: protocol('DNS','Domain Name System','Looks up resource records by name, such as A or AAAA records for IP addresses. DNS does more than convert domain names to IP addresses.',[
    topic('Recursion and iteration','Clients usually ask a recursive resolver for a final answer. The resolver can query root, top-level domain and authoritative servers, or use cached results.'),
    topic('Common records','A records contain IPv4 addresses, AAAA records IPv6 addresses, CNAME records aliases, and MX records mail routing information. TTL controls how long a record can remain cached.'),
    topic('UDP or TCP?','Traditional DNS supports both UDP and TCP port 53. Queries may start over UDP and retry over TCP after a truncated response. Zone transfers commonly use TCP. DoT and DoH provide encrypted DNS transport.')
  ],'UDP / TCP 53','https://www.rfc-editor.org/rfc/rfc1035.html'),
  smtp: protocol('SMTP','Mail submission and relay','Transfers mail from clients to mail servers and between mail servers.',[
    topic('Sending versus retrieving','SMTP submits and relays mail. IMAP and POP3 access or retrieve mail stored on a server; these roles are different.'),
    topic('Ports and security','Server-to-server relay commonly uses TCP 25, client submission 587, and implicit TLS submission 465. Encryption depends on configuration and negotiation.')
  ],'TCP 25 / 587 / 465','https://www.rfc-editor.org/rfc/rfc5321.html'),
  dhcp: protocol('DHCP','Automatic network configuration','DHCPv4 can supply IP addresses, subnet masks, default gateways, DNS servers and other configuration.',[
    topic('The four DORA steps','The typical sequence is Discover, Offer, Request and ACK. Initially the host lacks a usable address, so it uses mechanisms such as broadcast.'),
    topic('Leases and renewal','Addresses normally have leases that clients must renew. DHCPv6 is a separate protocol using UDP 546/547. IPv6 can also configure addresses through SLAAC.')
  ],'UDP 67 / 68','https://www.rfc-editor.org/rfc/rfc2131.html'),
  ssh: protocol('SSH','Secure remote access','Provides encrypted remote login, command execution and related channels.',[
    topic('Authentication and encryption','Key negotiation and server identity verification normally precede user authentication. Server host keys and user public keys serve different purposes.'),
    topic('Beyond a remote terminal','An SSH connection can carry multiple logical channels, including terminals, SFTP and port forwarding, sharing one underlying connection.')
  ],'TCP 22','https://www.rfc-editor.org/rfc/rfc4251.html'),
  tls: protocol('TLS','Encryption and identity authentication','Provides confidentiality, integrity protection and authentication for application data. Its placement here illustrates presentation functions rather than a strict OSI assignment.',[
    topic('What the handshake does','Peers negotiate parameters, establish keys and authenticate identities as needed. Clients usually verify the server certificate and target name; some deployments also authenticate clients.'),
    topic('Relation to HTTPS','A common HTTPS stack is HTTP → TLS → TCP → IP. QUIC integrates the TLS 1.3 handshake, rather than simply carrying TLS records over TCP.'),
    topic('Reliability is not security','TCP reliability does not hide content. TLS certificate validation failures and TCP connection failures are different problems.')
  ],'Functional mapping','https://www.rfc-editor.org/rfc/rfc8446.html'),
  encoding: protocol('UTF-8','Character encoding','Converts characters to bytes that the receiver interprets using the same encoding. This is a presentation function, not a network transport protocol.',[
    topic('Why text becomes garbled','Different encodings can interpret the same bytes differently. A protocol must specify an encoding or provide explicit encoding information.'),
    topic('Characters and bytes','One character need not equal one byte. UTF-8 is variable-length; distinguish character counts from byte counts.')
  ],'Data representation','https://www.rfc-editor.org/rfc/rfc3629.html'),
  json: protocol('JSON','Data serialization format','Represents objects, arrays and numbers as text so programs in different languages can exchange data. JSON itself is not a transport protocol.',[
    topic('Serialization and deserialization','Serialization encodes program objects into transferable bytes; deserialization reconstructs data structures. The application must still agree on field meanings.'),
    topic('Format versus transport','HTTP, WebSocket and other protocols can carry JSON. JSON does not automatically resolve message boundaries in a TCP byte stream.')
  ],'Data format','https://www.rfc-editor.org/rfc/rfc8259.html'),
  rpc: protocol('RPC','Remote procedure call','Lets programs request remote operations much like function calls. Concrete RPC systems often handle session-related functions.',[
    topic('Correlating requests and state','Call identifiers associate responses with requests. A timeout does not reveal whether the remote operation ran; consider idempotency and retries.'),
    topic('A note on layer placement','RPC is normally an application-layer mechanism in TCP/IP. It illustrates session management here, not a universal assignment to OSI layer five.')
  ],'Session-function example','https://www.rfc-editor.org/rfc/rfc5531.html'),
  session: protocol('SESSION','Application session management','Identifies an ongoing interaction across requests, such as a login or collaborative task. This is a family of mechanisms, not one standard protocol.',[
    topic('Three different concepts','The OSI session layer, a website login session and a TCP connection are distinct. One login may span connections; one connection may handle many requests.'),
    topic('Synchronization and recovery','Some session mechanisms use checkpoints or task identifiers to recover communication. Resumption depends on application design; TCP alone does not provide it.')
  ],'Mechanism example'),
  tcp: protocol('TCP','Reliable, ordered byte stream','After connection establishment, provides a reliable, ordered byte stream between transport endpoints. A connection is protocol state, not a dedicated physical circuit.',[
    topic('seq, ACK and ack','seq is a byte-counted sequence number. ACK is a control flag indicating that the acknowledgment field is valid; ack usually identifies the next expected byte. SYN and FIN each consume one sequence number.'),
    topic('Three-way handshake','A sends SYN(seq=100), B replies SYN+ACK(seq=500, ack=101), and A replies ACK(seq=101, ack=501). Both establish state and synchronize sequence numbers. The third acknowledgment confirms to B that its SYN arrived.'),
    topic('Four-segment close','TCP closes each direction independently, typically with FIN, ACK, FIN, ACK. ACK and FIN can sometimes be combined. The active closer usually enters TIME-WAIT to let old segments expire and allow the final ACK to be repeated.'),
    topic('Reliable delivery','Sequence numbers, acknowledgments, retransmission, ordering and duplicate removal provide reliability. Timeouts and connection failures still reach the application; reliable service does not mean networks never fail.'),
    topic('Flow and congestion control','Flow control protects receiver capacity; congestion control limits pressure on the network. Receive and congestion windows constrain the amount that may be sent.'),
    topic('Why reads do not match writes','TCP has no application message boundaries. Two sends may arrive in one read; one send may require several reads. Applications need length fields, delimiters or another framing scheme.')
  ],'Header ≥20 bytes','https://www.rfc-editor.org/rfc/rfc9293.html'),
  udp: protocol('UDP','Datagrams with message boundaries','Transfers datagrams without a TCP-style handshake. UDP itself guarantees neither delivery, order nor duplicate removal.',[
    topic('Four header fields','Source port, destination port, length and checksum are each 16 bits, giving an 8-byte header. The checksum detects errors; it does not correct them or retransmit data.'),
    topic('Message boundaries','UDP does not merge two datagrams into a byte stream. Some APIs truncate datagrams when receive buffers are too small; applications must size buffers correctly.'),
    topic('Loss and reordering','Sending 1, 2, 3 may yield 3, 1 or no arrivals. UDP does not automatically resend 2; applications may add sequence numbers, acknowledgments and retransmission.'),
    topic('Performance and applications','Common uses include DNS, real-time media and QUIC. A small UDP header does not make every workload faster. Consider congestion control, path MTU and fragmentation.')
  ],'8-byte header','https://www.rfc-editor.org/rfc/rfc768.html'),
  quic: protocol('QUIC','Secure transport over UDP','Implements reliability, encryption and multiplexing over UDP. It is the transport used by HTTP/3.',[
    topic('Where reliability comes from','UDP carries datagrams; QUIC implements acknowledgments, loss detection, recovery and congestion control. Using UDP does not require an unreliable application.'),
    topic('Multiple streams and migration','Independent stream delivery reduces transport head-of-line blocking between streams. Connection IDs can enable path migration under suitable conditions. Ordering still applies within a stream.')
  ],'Transport over UDP','https://www.rfc-editor.org/rfc/rfc9000.html'),
  ipv4: protocol('IPv4','Addressing and forwarding across networks','Identifies interfaces with 32-bit addresses and forwards IP packets hop by hop through routers, providing best-effort service.',[
    topic('Addresses, masks and gateways','A prefix determines whether a destination is local. Packets for remote networks usually go to a next-hop gateway. Example host A is 192.168.1.10/24.'),
    topic('Routing and TTL','Routing tables use rules such as longest-prefix matching to choose a next hop. Routers decrement TTL to prevent endless loops; they need not inspect all application content.'),
    topic('Fragmentation and MTU','When allowed, IPv4 fragmentation may occur at the source or routers; reassembly occurs at the destination. Fragmentation adds overhead, so modern transports usually try to avoid it using path MTU information.'),
    topic('The NAT exception','Normal routing generally preserves source and destination IP addresses. NAT rewrites addresses; NAPT may also rewrite ports. This simplified model does not simulate NAT.')
  ],'32-bit addresses','https://www.rfc-editor.org/rfc/rfc791.html'),
  ipv6: protocol('IPv6','Internet Protocol with 128-bit addresses','Uses a larger address space, a 40-byte base header and extension headers.',[
    topic('Address notation','Addresses use hexadecimal and colons. Consecutive zeros can be compressed by rule; 2001:db8::1 is a documentation address. The double-colon abbreviation can occur only once in an address.'),
    topic('Neighbor discovery','IPv6 uses ICMPv6-based Neighbor Discovery to resolve link addresses and discover routers, rather than IPv4 ARP.'),
    topic('Different fragmentation rules','IPv6 routers do not fragment. The source can use a Fragment extension header when needed. Hop Limit serves a role similar to IPv4 TTL.')
  ],'128-bit addresses','https://www.rfc-editor.org/rfc/rfc8200.html'),
  icmp: protocol('ICMP','Network errors and diagnostics','Reports some IP processing problems and supports diagnostics, including unreachable destinations, time exceeded and echo messages.',[
    topic('ping and traceroute','ping usually uses ICMP Echo Request/Reply. traceroute increases TTL/Hop Limit and observes time-exceeded messages to infer a path; its probe protocol may vary.'),
    topic('Not a reliability layer','ICMP does not guarantee packet delivery. Policy may block ping; successful ping does not prove a TCP port or application works.')
  ],'No TCP/UDP ports','https://www.rfc-editor.org/rfc/rfc792.html'),
  ospf: protocol('OSPF','Link-state routing protocol','Routers exchange topology information and compute paths to destination networks. This is a control-plane protocol.',[
    topic('Control versus forwarding','Protocols such as OSPF help create routing information. IP forwarding uses the resulting table; it does not recompute the entire network topology for every packet.'),
    topic('OSPF and BGP','OSPFv2 runs directly over IP, protocol number 89. BGP runs over TCP 179 despite its routing-control role; routing protocols are not all network-layer protocols.')
  ],'IP protocol 89','https://www.rfc-editor.org/rfc/rfc2328.html'),
  ethernet: protocol('ETHERNET','Ethernet frames and MAC addressing','Transfers frames on Ethernet links. Ethernet standards cover both data-link and physical functions.',[
    topic('Frame header and trailer','Common frames contain destination MAC, source MAC, EtherType, payload and FCS. FCS detects errors; it does not guarantee automatic Ethernet retransmission.'),
    topic('How switches learn','Layer-two switches learn interfaces from source MAC addresses and forward using destination MAC addresses. Unknown destinations may be flooded; broadcasts stay within the relevant broadcast domain.'),
    topic('New encapsulation at each hop','When A sends to remote B, the first frame usually targets the gateway MAC. After IP routing, the router uses a new link-layer header on the next link.')
  ],'MAC usually 48 bits'),
  wifi: protocol('WI-FI','Wireless LAN','IEEE 802.11 specifies wireless medium access, frame formats and physical transmission.',[
    topic('A shared wireless medium','CSMA/CA commonly coordinates access through sensing, backoff and acknowledgments. Wireless link acknowledgments differ from end-to-end TCP acknowledgments.'),
    topic('Multiple address fields','802.11 frames may contain several MAC address fields whose meanings depend on frame type and direction. Do not assume the two-address Ethernet layout.')
  ],'Link + physical'),
  arp: protocol('ARP','IPv4 next-hop address resolution','Resolves a next-hop IPv4 address to a link address on the local link, at the network/link-layer boundary.',[
    topic('Whose MAC is needed?','For a local destination, resolve its MAC. For a remote destination, usually resolve the gateway MAC rather than broadcast for the remote server MAC.'),
    topic('Requests and caching','Ethernet ARP requests are usually broadcast and replies usually unicast. Cached mappings reduce queries. ARP is carried directly by the link, not inside a normal IP packet.')
  ],'Does not use TCP/UDP ports','https://www.rfc-editor.org/rfc/rfc826.html'),
  vlan: protocol('802.1Q','Virtual LAN','Divides a switched network into layer-two broadcast domains and tags frame membership.',[
    topic('Broadcast domains and routing','Communication between VLANs usually needs layer-three forwarding. VLANs provide layer-two segmentation, not encryption.'),
    topic('Access and trunk','Access ports typically attach endpoints to one VLAN; trunk links carry several VLANs. Tagging depends on port configuration.')
  ],'Layer-two segmentation'),
  phy: protocol('PHY','Physical transmission and encoding','Defines signals, electrical or optical properties, timing, modulation and coding so receivers can recover bits.',[
    topic('Bits are not characters','The physical layer carries encoded signals. It does not parse HTTP status codes or deliver data to applications by port.'),
    topic('Rate, bandwidth and delay','Link rate is the number of bits transferable per unit time, not available end-to-end throughput. Propagation delay also depends on distance and medium.'),
    topic('Duplex modes','Full duplex supports simultaneous transmission in both directions; half duplex permits only one direction at a time. Modern switched Ethernet normally uses full duplex.')
  ],'Signals and bits'),
  medium: protocol('MEDIA','Copper, fiber and wireless','The medium determines signal propagation and affects distance, interference resistance and deployment. A medium is not an application protocol.',[
    topic('Copper cable','Twisted pairs carry electrical signals; twisting reduces interference. Standards, cables and conditions constrain distance and rate.'),
    topic('Optical fiber','Carries light, suitable for long distances and high-capacity links. Compatible optical modules and link specifications are still required.'),
    topic('Wireless','Electromagnetic propagation depends on frequency, obstacles, interference and shared access. A strong signal does not guarantee high application throughput.')
  ],'Transmission medium')
};

export const OSI = [
 {id:'application',number:7,name:'Application layer',en:'Application',color:'#68bba5',question:'What rules do applications use to communicate?',unit:'Messages / application data',scope:'Application to application',definition:'Defines communication rules for particular tasks: request and response formats, field meanings and error handling. It provides network services to applications; it is not the browser or chat program itself.',analogy:'Like agreeing on a letter format so the recipient understands the request.',features:[['Message semantics','Defines request methods, resources, status codes and message fields.'],['Service and resource access','Supports web access, name lookup, email and remote access.'],['Using lower-layer services','Uses TCP, UDP or other transport mechanisms as required.']],protocols:['http','dns','smtp','dhcp','ssh'],process:'The sender creates an HTTP request or DNS query; the receiver parses it for the application. In TCP/IP, applications, protocols and libraries also commonly perform presentation and session functions.',mistakes:[['The application layer is not the application','A browser is a program; HTTP is an application-layer protocol it uses.'],['Application protocols need not use TCP','DNS can use UDP or TCP; HTTP/3 runs over QUIC.']]},
 {id:'presentation',number:6,name:'Presentation layer',en:'Presentation',color:'#91bba2',question:'How do both peers interpret the same bytes consistently?',unit:'Data',scope:'Data representation and conversion',definition:'Coordinates representation, including encoding, serialization, compression and encryption. OSI divides functions; real TCP/IP systems often implement these in applications or libraries rather than a separate sixth-layer module.',analogy:'Like agreeing on a language and format that both sides can read.',features:[['Encoding and serialization','Converts characters and objects into transferable bytes.'],['Compression and conversion','Reduces data size when needed and reconstructs it using agreed rules.'],['Encryption functions','Protects content; placement depends on the protocol stack.']],protocols:['encoding','json','tls'],process:'This demonstration treats representation as a functional stage. It need not add a separate fixed header to each message. Real protocols such as TLS have their own structures.',mistakes:[['A format is not a network protocol','JSON and UTF-8 are formats or encodings that illustrate presentation functions.'],['TLS has no absolute OSI placement','TLS commonly runs between an application protocol and TCP; its placement here is functional.']]},
 {id:'session',number:5,name:'Session layer',en:'Session',color:'#b4bd8b',question:'How is an ongoing interaction organized and managed?',unit:'Data',scope:'Dialogue management',definition:'In OSI, organizes sessions, coordinates dialogues, establishes synchronization points and supports some recovery procedures. Internet applications and protocols often share these responsibilities.',analogy:'Like a meeting with an agenda, turn-taking and an agreed point for resuming after interruption.',features:[['Session lifecycle','Organizes session establishment, management and termination.'],['Dialogue and synchronization','Coordinates interactions and synchronization points as needed.'],['Recovery mechanisms','Recovery depends on the specific protocol and application.']],protocols:['rpc','session'],process:'This demonstration treats session management as a functional stage without inventing a fixed session header. HTTP login management remains application-layer behavior in TCP/IP.',mistakes:[['A login session is not a TCP connection','One login session may span multiple TCP connections.'],['No universal Internet session module','Not every OSI function corresponds to a separate software component.']]},
 {id:'transport',number:4,name:'Transport layer',en:'Transport',color:'#a4a6d0',question:'Which application receives the data, and with what delivery guarantees?',unit:'TCP segments / UDP datagrams',scope:'End to end / between processes',definition:'Provides communication between host transport endpoints, using mechanisms such as ports for multiplexing and demultiplexing. TCP supplies an ordered reliable byte stream; UDP preserves datagram boundaries.',analogy:'IP delivers a letter to a building; a port helps deliver it to the correct department.',features:[['Ports and demultiplexing','Ports are 16-bit integers. TCP and UDP have separate port spaces.'],['Service trade-offs','Reliability, ordering and overhead depend on the chosen protocol.'],['Connections and control','TCP has connection state, flow control and congestion control.']],protocols:['tcp','udp','quic'],process:'The HTTP example adds a TCP header with source port 53000 and destination 80. DNS adds a UDP header with destination 53. The receiver removes the header and demultiplexes to the endpoint.',mistakes:[['TCP does not preserve message boundaries','Applications must define lengths, delimiters or protocol framing.'],['UDP is not always faster','Performance also depends on the network, application and higher-layer implementation.'],['Reliable delivery does not imply encryption','TCP alone does not provide content protection like TLS.']]},
 {id:'network',number:3,name:'Network layer',en:'Network',color:'#81b7cc',question:'Which next hop leads across these networks?',unit:'IP packets',scope:'Host to host / routing',definition:'Uses logical addresses such as IP for addressing and packet forwarding across networks. Routers choose next hops from routing information. IP is best effort: no delivery, order or duplicate-removal guarantee.',analogy:'Like choosing roads using city and street addresses, with a new decision at each junction.',features:[['Logical addressing','IPv4 addresses are 32 bits; IPv6 addresses are 128 bits.'],['Routing and forwarding','Uses routing tables, usually selecting a next hop by longest-prefix match.'],['Limiting packet lifetime','TTL or Hop Limit prevents forwarding loops from persisting indefinitely.']],protocols:['ipv4','ipv6','icmp','ospf'],process:'A is 192.168.1.10 and B is 192.168.2.20 in different /24 subnets. The router connects them. This example has no NAT: IP addresses stay unchanged and TTL decreases from 64 to 63.',mistakes:[['IP and MAC addresses are different','IP addresses work across networks; MAC addresses mainly serve local-link delivery.'],['Routers do not forward using MAC alone','Normal IP routing mainly uses the destination IP and routing table.']]},
 {id:'datalink',number:2,name:'Data-link layer',en:'Data Link',color:'#75b8b9',question:'How does this hop deliver a frame to the neighboring device?',unit:'Frame',scope:'One link / layer-two network',definition:'Encapsulates network-layer packets into frames, handling link addressing, medium access and error detection. Ethernet uses MAC addresses; reliability differs across link protocols.',analogy:'Like a handover note for one leg of a relay journey, naming only that leg of delivery.',features:[['Framing and addressing','Adds this hop of link headers and any required trailer.'],['Medium access','Coordinates transmissions on shared media.'],['Error detection','Mechanisms such as FCS detect errors without necessarily correcting or retransmitting them.']],protocols:['ethernet','wifi','arp','vlan'],process:'First hop: A-MAC → router left-interface MAC. Second hop: router right-interface MAC → B-MAC. The router creates new link encapsulation; link addresses change each hop.',mistakes:[['The remote server MAC is not the first-hop destination','Traffic for another subnet usually first goes to the local gateway.'],['Not every switch is purely layer two','Layer-three switches can also perform IP routing.']]},
 {id:'physical',number:1,name:'Physical layer',en:'Physical',color:'#a6b4c2',question:'How do bits become signals that can propagate?',unit:'Bits / signals',scope:'Transmission medium',definition:'Specifies interfaces, coding, modulation and timing for carrying bits through electrical, optical or wireless signals. It does not parse IP addresses, ports or application content.',analogy:'Like the roads and vehicles carrying information organized by the higher layers.',features:[['Signals and media','Copper uses electricity, fiber uses light, and wireless uses electromagnetic waves.'],['Encoding and synchronization','Both sides recover bits according to the relevant specifications.'],['Physical interfaces and rates','Specifies connections, electrical/optical properties and transmission capability.']],protocols:['phy','medium'],process:'Frames become signals on the first link, are processed by the router, then transmitted on the next link. Higher-layer protocols do not connect directly through the air.',mistakes:[['Line rate is not actual throughput','Protocol overhead, congestion and endpoint capability affect throughput.'],['The physical layer adds no ordinary protocol header','It handles signal transmission and coding rather than message semantics.']]}
];

export const TCPIP = [
 {...OSI[0],id:'tcp-application',number:4,en:'Application',definition:'The TCP/IP application layer covers most OSI application, presentation and session functions. Applications and libraries also handle representation, sessions and encryption.',scope:'Application protocols and related mechanisms',protocols:['http','dns','smtp','dhcp','ssh','tls','json'],process:'Applications generate messages, encode them and manage sessions before transport. Four layers are a different organization of functions, not simply seven layers with three deleted.',mistakes:[['The four-layer model is not TCP/UDP','Its name is TCP/IP; TCP and UDP are both transport protocols.'],['Mappings summarize functions','Mechanisms such as TLS cannot be rigidly assigned to one OSI layer.']]},
 {...OSI[3],id:'tcp-transport',number:3},
 {...OSI[4],id:'internet',number:2,name:'Internet layer',en:'Internet'},
 {...OSI[5],id:'interface',number:1,name:'Network access layer',en:'Network Access',unit:'Frames / bits',scope:'Link and physical transmission',definition:'Sends and receives IP packets on a specific network, combining OSI data-link and physical functions: frames, link addresses, medium access and signals.',question:'How are frames and signals actually sent on this hop?',features:[['Frames and link addresses','Encapsulates IP packets for the current link and selects a receiving interface.'],['Encoding and media','Turns frames into signals carried over wired or wireless media.'],['Hop-by-hop delivery','Encapsulation, addresses and signaling may differ on each link.']],protocols:['ethernet','wifi','arp','vlan','phy','medium'],process:'Frames and signals are sent separately on A-to-router and router-to-B links. The router replaces link headers while preserving IP addresses in this example without NAT.'}
];

export const LABS = {
 handshake:{title:'TCP three-way handshake',subtitle:'Synchronize sequence numbers · Establish connection state',footnote:'Classic handshake without data, initiated by A. SYN consumes one sequence number; a pure ACK consumes none.',steps:[
  {title:'A → B: Send SYN',description:'A chooses initial sequence number 100 and requests a connection, entering SYN-SENT. B receives SYN, enters SYN-RECEIVED and prepares a reply.',direction:1,wire:'SYN=1  ACK=0\nseq=100',states:['SYN-SENT','SYN-RECEIVED'],tag:'SYN · seq 100'},
  {title:'B → A: Reply SYN + ACK',description:'B acknowledges A with ack=101 and chooses initial sequence 500. A enters ESTABLISHED on receipt; B remains in SYN-RECEIVED awaiting the final acknowledgment.',direction:-1,wire:'SYN=1  ACK=1\nseq=500  ack=101',states:['ESTABLISHED','SYN-RECEIVED'],tag:'SYN+ACK · ack 101'},
  {title:'A → B: Acknowledge B SYN',description:'A enters ESTABLISHED after receiving SYN+ACK and sends ack=501. B receives this ACK and enters ESTABLISHED, completing the handshake.',direction:1,wire:'SYN=0  ACK=1\nseq=101  ack=501',states:['ESTABLISHED','ESTABLISHED'],tag:'ACK · ack 501'}
 ]},
 close:{title:'TCP four-segment close',subtitle:'Close each direction separately · Half-close supported',footnote:'Typical four separate segments with no outstanding data. ACK and FIN may be combined in practice. Both peers start in ESTABLISHED.',steps:[
  {title:'A → B: No more data to send',description:'A sends FIN(seq=1000), entering FIN-WAIT-1. B enters CLOSE-WAIT. Only A-to-B sending closes; A can still receive data from B.',direction:1,wire:'FIN=1  ACK=1\nseq=1000  ack=2000',states:['FIN-WAIT-1','CLOSE-WAIT'],tag:'FIN · seq 1000'},
  {title:'B → A: Acknowledge A FIN',description:'B enters CLOSE-WAIT and replies ack=1001. A enters FIN-WAIT-2; B may continue sending remaining data.',direction:-1,wire:'ACK=1\nseq=2000  ack=1001',states:['FIN-WAIT-2','CLOSE-WAIT'],tag:'ACK · ack 1001'},
  {title:'B → A: No more data from B',description:'After its application finishes sending, B sends FIN and enters LAST-ACK. There was no intervening data here, so seq remains 2000.',direction:-1,wire:'FIN=1  ACK=1\nseq=2000  ack=1001',states:['FIN-WAIT-2','LAST-ACK'],tag:'FIN · seq 2000'},
  {title:'A → B: Final acknowledgment',description:'A receives FIN, sends ack=2001 and enters TIME-WAIT. B receives ACK and becomes CLOSED. A normally waits 2MSL before CLOSED to handle old segments and loss of the final ACK.',direction:1,wire:'ACK=1\nseq=1001  ack=2001',states:['TIME-WAIT','CLOSED'],tag:'ACK · ack 2001'}
 ]},
 udp:{title:'UDP datagram transfer',subtitle:'Preserve message boundaries · No delivery or ordering guarantee',footnote:'Deliberate teaching example: datagram 2 is lost and 3 arrives first. UDP need not lose data; underlying TCP paths can also lose packets.',steps:[
  {title:'A sends datagram ①',description:'The application submits an independent datagram without a TCP-style handshake. It is delayed in this example. Numbering is application-defined; the UDP header has no sequence number.',direction:1,wire:'UDP 53000 → 9000\nApplication ID=1  Content=HELLO',states:['No TCP connection state','Waiting for a datagram'],tag:'Datagram ① · delayed',delay:true},
  {title:'Datagram ② is lost on the link',description:'The second datagram is deliberately discarded. UDP does not automatically acknowledge or retransmit it; the receiver may never know it existed.',direction:1,wire:'UDP 53000 → 9000\nApplication ID=2  Content=NETWORK',states:['No automatic retransmission','Not received yet'],tag:'Datagram ② · lost',drop:true},
  {title:'B receives datagram ③ first',description:'The third datagram arrives first, so the application can read ID 3 first. UDP does not sort datagrams into 1, 2, 3; message boundaries remain intact.',direction:1,wire:'UDP 53000 → 9000\nApplication ID=3  Content=WORLD',states:['Sending continues','Received: ③'],tag:'Datagram ③ · arrived'},
  {title:'Delayed datagram ① finally arrives',description:'B receives the first datagram. Arrival order is ③, ①; ② never arrives. Reliability and ordering require higher-layer mechanisms when needed.',direction:1,wire:'Arrival order: ③ → ①\nMissing: ②; no automatic UDP retransmission',states:['Sending complete','Received: ③, ①'],tag:'Datagram ① · arrived'}
 ]}
};
